using System;
using System.Data;
using System.Web.UI;
using System.Web.UI.WebControls;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Controls.TeacherWork
{
    /// <summary>
    /// Chi tiết khối lượng GV — port view từ frmTeachingTimeAdded_V2, frmBangTinhGioDayGiangVien, frmThongKeGioCoiThiChamThi (mẫu chi tiết).
    /// </summary>
    public partial class TeacherWorkloadDetail : ControlBase
    {
        #region Page lifecycle

        protected void Page_Load(object sender, EventArgs e)
        {
            uTeacher.SearchClick += new UTeacherFilter.SearchDelegate(uTeacher_SearchClick);
            uYearSemester.EditValueChanged += new UYearSemesterFilter.EditValueChangedDelegate(uYearSemester_EditValueChanged);

            if (!IsPostBack)
            {
                if (User == null)
                {
                    MsgBox.ShowWarning("Chức năng này chỉ dành cho nhà quản lý, vui lòng đăng nhập!");
                    Response.Redirect("~/");
                    return;
                }

                uTeacher.ShowSearchButton = false;
                uYearSemester.LoadData();
                LoadTeacherWork();

                if (WebGlobal.StudentID == 0)
                {
                    uTeacher.TeacherID = User.UserName.ToLower();
                    if (uYearSemester.YearID != null && (chkFullYear.Checked || uYearSemester.Semester != null))
                        ReadAllData();
                }
            }
        }

        #endregion

        #region Filter / reference

        private void uTeacher_SearchClick(object scienceID, object subjectGroupID, object teacherID)
        {
            btnSearch_Click(null, null);
        }

        private void uYearSemester_EditValueChanged(object yearID, object semester)
        {
            LoadTeacherWork();
        }

        protected void chkFullYear_CheckedChanged(object sender, EventArgs e)
        {
            uYearSemester.SemesterEnabled = !chkFullYear.Checked;
            LoadTeacherWork();
        }

        private object NormalizeFilterValue(object value)
        {
            if (value == null || value == DBNull.Value)
                return null;
            if (value.ToString().Trim() == "")
                return null;
            return value;
        }

        private object GetTeacherWorkIDFilter()
        {
            if (ddlTeacherWorkID.SelectedValue == null || ddlTeacherWorkID.SelectedValue == "")
                return null;
            return Convert.ToInt32(ddlTeacherWorkID.SelectedValue);
        }

        private void LoadTeacherWork()
        {
            if (uYearSemester.YearID == null)
                return;

            object semester = null;
            if (!chkFullYear.Checked && uYearSemester.Semester != null)
                semester = Convert.ToInt32(uYearSemester.Semester);

            SIM_TeacherWork obj = new SIM_TeacherWork();
            DataTable dtb = obj.GetDataTable("SIM_TeacherWork_SearchCbx",
                "@YearID", uYearSemester.YearID,
                "@Semester", semester);

            if (dtb == null)
                return;

            WebGlobal.InitDropDownList(ddlTeacherWorkID, dtb, "TeacherWorkID", "TeacherWorkName", "--Chọn--");
        }

        private bool IsValidData()
        {
            if (uYearSemester.YearID == null)
            {
                MsgBox.ShowWarning("Bạn phải chọn niên học!");
                return false;
            }

            if (!chkFullYear.Checked && uYearSemester.Semester == null)
            {
                MsgBox.ShowWarning("Bạn phải chọn học kỳ (hoặc chọn Cả năm cho tab công việc khác)!");
                return false;
            }

            return true;
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            ReadAllData();
        }

        #endregion

        #region Load data

        private void ReadAllData()
        {
            LoadTeachingTimeAdded();
            LoadBangTinhGioDay();
            LoadCoiThiChamThiChiTiet();
            udpMain.Update();
        }

        private void LoadTeachingTimeAdded()
        {
            ResetSumAdded();
            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
            DataTable dtbData = null;

            object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
            object subjectGroupID = NormalizeFilterValue(uTeacher.SubjectGroupID);
            object teacherID = NormalizeFilterValue(uTeacher.TeacherID);
            object teacherWorkID = GetTeacherWorkIDFilter();

            if (chkFullYear.Checked)
            {
                DataTable dtbSemester1 = SearchTeachingTimeAdded(obj, scienceID, subjectGroupID, teacherID, teacherWorkID, 1);
                DataTable dtbSemester2 = SearchTeachingTimeAdded(obj, scienceID, subjectGroupID, teacherID, teacherWorkID, 2);

                bool bolHas1 = dtbSemester1 != null && dtbSemester1.Rows.Count > 0;
                bool bolHas2 = dtbSemester2 != null && dtbSemester2.Rows.Count > 0;

                if (!bolHas1 && !bolHas2)
                {
                    BindRepeaterEmpty(rptTeachingTimeAdded, ltrEmptyAdded, "Không có dữ liệu công việc khác!");
                    return;
                }

                if (bolHas1 && bolHas2)
                {
                    dtbData = dtbSemester1.Copy();
                    foreach (DataRow drw in dtbSemester2.Rows)
                        dtbData.ImportRow(drw);
                }
                else if (bolHas1)
                    dtbData = dtbSemester1.Copy();
                else
                    dtbData = dtbSemester2.Copy();
            }
            else
            {
                int semester = Convert.ToInt32(uYearSemester.Semester);
                dtbData = SearchTeachingTimeAdded(obj, scienceID, subjectGroupID, teacherID, teacherWorkID, semester);
            }

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                BindRepeaterEmpty(rptTeachingTimeAdded, ltrEmptyAdded, "Không có dữ liệu công việc khác!");
                return;
            }

            EnsureStandardHourColumn(dtbData);
            CalcSumAdded(dtbData);
            BindRepeater(rptTeachingTimeAdded, ltrEmptyAdded, dtbData);
        }

        private DataTable SearchTeachingTimeAdded(SIM_TeachingTimeAdded obj, object scienceID, object subjectGroupID,
            object teacherID, object teacherWorkID, int semester)
        {
            DataTable dtb = obj.GetDataTable("SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                "@ScienceID", scienceID,
                "@SubjectGroupID", subjectGroupID,
                "@TeacherID", teacherID,
                "@YearID", uYearSemester.YearID,
                "@Semester", semester,
                "@TeacherWorkID", teacherWorkID);

            if (dtb != null)
                EnsureYearSemesterColumns(dtb, semester);

            return dtb;
        }

        private void EnsureYearSemesterColumns(DataTable dtb, int semester)
        {
            if (!dtb.Columns.Contains("YearID"))
                dtb.Columns.Add("YearID", typeof(int));
            if (!dtb.Columns.Contains("YearText"))
                dtb.Columns.Add("YearText", typeof(string));
            if (!dtb.Columns.Contains("Semester"))
                dtb.Columns.Add("Semester", typeof(int));

            int yearId = Convert.ToInt32(uYearSemester.YearID);
            string yearText = uYearSemester.YearText;
            if (yearText == null || yearText == "")
                yearText = String.Format("{0}-{1}", yearId, yearId + 1);

            foreach (DataRow drw in dtb.Rows)
            {
                drw["YearID"] = yearId;
                drw["YearText"] = yearText;
                drw["Semester"] = semester;
            }
        }

        private void EnsureStandardHourColumn(DataTable dtb)
        {
            if (!dtb.Columns.Contains("StandardHour"))
                dtb.Columns.Add("StandardHour", typeof(decimal));

            foreach (DataRow drw in dtb.Rows)
                CalculateStandardHour(drw);
        }

        private void CalculateStandardHour(DataRow drw)
        {
            if (drw == null)
                return;

            if (drw["RequestTotal"] == DBNull.Value || drw["RequestTotal"].ToString().Trim() == "")
            {
                drw["StandardHour"] = DBNull.Value;
                return;
            }

            decimal requestTotal = Convert.ToDecimal(drw["RequestTotal"]);
            int teacherWorkId = Convert.ToInt32(drw["TeacherWorkID"]);
            decimal standardHour = 0;

            if (teacherWorkId == 35)
                standardHour = requestTotal * 52m / 160m;
            else if (teacherWorkId == 34)
                standardHour = requestTotal * 26m / 80m;
            else
            {
                drw["StandardHour"] = DBNull.Value;
                return;
            }

            drw["StandardHour"] = Math.Round(standardHour, 2, MidpointRounding.AwayFromZero);
        }

        private void LoadBangTinhGioDay()
        {
            ResetSumTeaching();
            SIM_Branch obj = new SIM_Branch();

            object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
            object subjectGroupID = NormalizeFilterValue(uTeacher.SubjectGroupID);
            object teacherID = NormalizeFilterValue(uTeacher.TeacherID);
            object semester = null;
            if (!chkFullYear.Checked && uYearSemester.Semester != null)
                semester = uYearSemester.Semester;

            DataTable dtbData = obj.GetDataTable(
                "SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New",
                "@ScienceID", scienceID,
                "@SubjectGroupID", subjectGroupID,
                "@TeacherID", teacherID,
                "@YearID", uYearSemester.YearID,
                "@Semester", semester,
                "@IsContractTeaching", chkIsContractTeaching.Checked
            );

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                BindRepeaterEmpty(rptTeachingHour, ltrEmptyTeaching, "Không có dữ liệu giờ dạy!");
                return;
            }

            if (!dtbData.Columns.Contains("SubjectName") || !dtbData.Columns.Contains("HeSo"))
            {
                BindRepeaterEmpty(rptTeachingHour, ltrEmptyTeaching,
                    "Store chưa cập nhật đủ cột (SubjectName, HeSo). Hãy chạy script SIM_WeekDetailPlan_BangTinhGioDayGiangVien_New trên database.");
                return;
            }

            ApplyQuyDoiColumns(dtbData);
            CalcSumTeaching(dtbData);
            BindRepeater(rptTeachingHour, ltrEmptyTeaching, dtbData);
        }

        /// <summary>
        /// Quy đổi giờ dạy — cùng công thức frmBangTinhGioDayGiangVien / frmBangTongHopGioChiTietGiangVien:
        /// (LT + TH) × HeSo × HeSoSiSo(sĩ số). Giữ QuyDoiGio từ store nếu đã có.
        /// </summary>
        private void ApplyQuyDoiColumns(DataTable dt)
        {
            if (!dt.Columns.Contains("TongLTTH"))
                dt.Columns.Add("TongLTTH", typeof(decimal));

            if (!dt.Columns.Contains("QuyDoiGio"))
                dt.Columns.Add("QuyDoiGio", typeof(decimal));

            foreach (DataRow row in dt.Rows)
            {
                decimal lt = ToDecimal(row["TotalQuantity_Theory"]);
                decimal th = ToDecimal(row["TotalQuantity_Practice"]);
                decimal heSo = ToDecimal(row["HeSo"]);
                decimal classSize = ToDecimal(row["ClassSize"]);

                if (heSo == 0)
                    heSo = 1;

                decimal tong = lt + th;
                row["TongLTTH"] = tong;

                if (row["QuyDoiGio"] != DBNull.Value && ToDecimal(row["QuyDoiGio"]) > 0)
                    continue;

                row["QuyDoiGio"] = tong * heSo * GetHeSoSiSo(classSize);
            }
        }

        private static decimal GetHeSoSiSo(decimal classSize)
        {
            if (classSize <= 35)
                return 1.00m;

            if (classSize >= 36 && classSize <= 50)
                return 1.10m;

            if (classSize >= 51)
                return 1.20m;

            return 1.00m;
        }

        private static decimal ToDecimal(object value)
        {
            if (value == null || value == DBNull.Value)
                return 0;

            return Convert.ToDecimal(value);
        }

        private void LoadCoiThiChamThiChiTiet()
        {
            ResetSumExam();
            SIM_TestSchedule obj = new SIM_TestSchedule();

            object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
            object subjectGroupID = NormalizeFilterValue(uTeacher.SubjectGroupID);
            object teacherID = NormalizeFilterValue(uTeacher.TeacherID);
            object semester = null;
            if (!chkFullYear.Checked && uYearSemester.Semester != null)
                semester = uYearSemester.Semester;

            DataTable dtbData = obj.GetDataTable("SIM_Schedule_TKGioCoiThiChamThi_ChiTiet",
                "@YearID", uYearSemester.YearID,
                "@Semester", semester,
                "@ScienceIDOfTeacher", scienceID,
                "@SubjectGroupIDOfTeacher", subjectGroupID,
                "@TeacherID", teacherID);

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                BindRepeaterEmpty(rptExamDetail, ltrEmptyExam, "Không có dữ liệu coi thi - chấm thi!");
                return;
            }

            ApplyExamQuyDoiColumns(dtbData);
            CalcSumExam(dtbData);
            BindRepeater(rptExamDetail, ltrEmptyExam, dtbData);
        }

        /// <summary>
        /// Quy đổi giờ coi/chấm thi — cùng công thức #tbl_CoiThi_ChamThi trong SIM_Schedule_TK_KetQuaThucHienNhaGiao.
        /// Giờ coi (thi + kiểm tra) * HeSo * 0.5; bài chấm (thi + kiểm tra) * HeSo * 0.1.
        /// </summary>
        private void ApplyExamQuyDoiColumns(DataTable dt)
        {
            if (!dt.Columns.Contains("GioQuyDoi_CoiThi"))
                dt.Columns.Add("GioQuyDoi_CoiThi", typeof(decimal));
            if (!dt.Columns.Contains("GioQuyDoi_ChamThi"))
                dt.Columns.Add("GioQuyDoi_ChamThi", typeof(decimal));
            if (!dt.Columns.Contains("TongGioQuyDoi"))
                dt.Columns.Add("TongGioQuyDoi", typeof(decimal));

            foreach (DataRow row in dt.Rows)
            {
                decimal heSo = ToDecimal(row["HeSo"]);
                decimal gioCoi = ToDecimal(row["SoGio_CoiThi"]) + ToDecimal(row["SoGio_CoiKiemTra"]);
                decimal baiCham = ToDecimal(row["SoBai_ChamThi"]) + ToDecimal(row["SoBai_ChamKiemTra"]);

                decimal gioQuyDoiCoiThi = Math.Round(gioCoi * heSo * 0.5m, 2, MidpointRounding.AwayFromZero);
                decimal gioQuyDoiChamThi = Math.Round(baiCham * heSo * 0.1m, 2, MidpointRounding.AwayFromZero);

                row["GioQuyDoi_CoiThi"] = gioQuyDoiCoiThi;
                row["GioQuyDoi_ChamThi"] = gioQuyDoiChamThi;
                row["TongGioQuyDoi"] = gioQuyDoiCoiThi + gioQuyDoiChamThi;
            }
        }

        #endregion

        #region Summary totals

        private bool _bolShowSumAdded;
        private decimal _sumAddedRequestQuantity;
        private decimal _sumAddedRequestTotal;
        private decimal _sumAddedStandardHour;

        private bool _bolShowSumTeaching;
        private decimal _sumTeachingLT;
        private decimal _sumTeachingTH;
        private decimal _sumTeachingTongLTTH;
        private decimal _sumTeachingQuyDoiGio;

        private bool _bolShowSumExam;
        private decimal _sumExamSoCaThi;
        private decimal _sumExamSoCaKiemTra;
        private decimal _sumExamSoGioCoiThi;
        private decimal _sumExamSoGioCoiKiemTra;
        private decimal _sumExamSoBaiChamThi;
        private decimal _sumExamSoBaiChamKiemTra;
        private decimal _sumExamGioQuyDoiCoiThi;
        private decimal _sumExamGioQuyDoiChamThi;
        private decimal _sumExamTongGioQuyDoi;

        protected bool ShowSumAdded
        {
            get { return _bolShowSumAdded; }
        }

        protected bool ShowSumTeaching
        {
            get { return _bolShowSumTeaching; }
        }

        protected bool ShowSumExam
        {
            get { return _bolShowSumExam; }
        }

        protected string SumAddedRequestQuantity
        {
            get { return FormatNumber(_sumAddedRequestQuantity); }
        }

        protected string SumAddedRequestTotal
        {
            get { return FormatNumber(_sumAddedRequestTotal); }
        }

        protected string SumAddedStandardHour
        {
            get { return FormatNumber(_sumAddedStandardHour); }
        }

        protected string SumTeachingLT
        {
            get { return FormatNumber(_sumTeachingLT); }
        }

        protected string SumTeachingTH
        {
            get { return FormatNumber(_sumTeachingTH); }
        }

        protected string SumTeachingTongLTTH
        {
            get { return FormatNumber(_sumTeachingTongLTTH); }
        }

        protected string SumTeachingQuyDoiGio
        {
            get { return FormatNumber(_sumTeachingQuyDoiGio); }
        }

        protected string SumExamSoCaThi
        {
            get { return FormatInteger(_sumExamSoCaThi); }
        }

        protected string SumExamSoCaKiemTra
        {
            get { return FormatInteger(_sumExamSoCaKiemTra); }
        }

        protected string SumExamSoGioCoiThi
        {
            get { return FormatNumber(_sumExamSoGioCoiThi); }
        }

        protected string SumExamSoGioCoiKiemTra
        {
            get { return FormatNumber(_sumExamSoGioCoiKiemTra); }
        }

        protected string SumExamSoBaiChamThi
        {
            get { return FormatNumber(_sumExamSoBaiChamThi); }
        }

        protected string SumExamSoBaiChamKiemTra
        {
            get { return FormatNumber(_sumExamSoBaiChamKiemTra); }
        }

        protected string SumExamGioQuyDoiCoiThi
        {
            get { return FormatNumber(_sumExamGioQuyDoiCoiThi); }
        }

        protected string SumExamGioQuyDoiChamThi
        {
            get { return FormatNumber(_sumExamGioQuyDoiChamThi); }
        }

        protected string SumExamTongGioQuyDoi
        {
            get { return FormatNumber(_sumExamTongGioQuyDoi); }
        }

        private void ResetSumAdded()
        {
            _bolShowSumAdded = false;
            _sumAddedRequestQuantity = 0;
            _sumAddedRequestTotal = 0;
            _sumAddedStandardHour = 0;
        }

        private void ResetSumTeaching()
        {
            _bolShowSumTeaching = false;
            _sumTeachingLT = 0;
            _sumTeachingTH = 0;
            _sumTeachingTongLTTH = 0;
            _sumTeachingQuyDoiGio = 0;
        }

        private void ResetSumExam()
        {
            _bolShowSumExam = false;
            _sumExamSoCaThi = 0;
            _sumExamSoCaKiemTra = 0;
            _sumExamSoGioCoiThi = 0;
            _sumExamSoGioCoiKiemTra = 0;
            _sumExamSoBaiChamThi = 0;
            _sumExamSoBaiChamKiemTra = 0;
            _sumExamGioQuyDoiCoiThi = 0;
            _sumExamGioQuyDoiChamThi = 0;
            _sumExamTongGioQuyDoi = 0;
        }

        private void CalcSumAdded(DataTable dtb)
        {
            if (dtb == null || dtb.Rows.Count == 0)
                return;

            _bolShowSumAdded = true;
            _sumAddedRequestQuantity = SumColumn(dtb, "RequestQuantity");
            _sumAddedRequestTotal = SumColumn(dtb, "RequestTotal");
            _sumAddedStandardHour = SumColumn(dtb, "StandardHour");
        }

        private void CalcSumTeaching(DataTable dtb)
        {
            if (dtb == null || dtb.Rows.Count == 0)
                return;

            _bolShowSumTeaching = true;
            _sumTeachingLT = SumColumn(dtb, "TotalQuantity_Theory");
            _sumTeachingTH = SumColumn(dtb, "TotalQuantity_Practice");
            _sumTeachingTongLTTH = SumColumn(dtb, "TongLTTH");
            _sumTeachingQuyDoiGio = SumColumn(dtb, "QuyDoiGio");
        }

        private void CalcSumExam(DataTable dtb)
        {
            if (dtb == null || dtb.Rows.Count == 0)
                return;

            _bolShowSumExam = true;
            _sumExamSoCaThi = SumColumn(dtb, "SoCa_Thi");
            _sumExamSoCaKiemTra = SumColumn(dtb, "SoCa_KiemTra");
            _sumExamSoGioCoiThi = SumColumn(dtb, "SoGio_CoiThi");
            _sumExamSoGioCoiKiemTra = SumColumn(dtb, "SoGio_CoiKiemTra");
            _sumExamSoBaiChamThi = SumColumn(dtb, "SoBai_ChamThi");
            _sumExamSoBaiChamKiemTra = SumColumn(dtb, "SoBai_ChamKiemTra");
            _sumExamGioQuyDoiCoiThi = SumColumn(dtb, "GioQuyDoi_CoiThi");
            _sumExamGioQuyDoiChamThi = SumColumn(dtb, "GioQuyDoi_ChamThi");
            _sumExamTongGioQuyDoi = SumColumn(dtb, "TongGioQuyDoi");
        }

        private decimal SumColumn(DataTable dtb, string colName)
        {
            if (dtb == null || !dtb.Columns.Contains(colName))
                return 0;

            decimal sum = 0;
            foreach (DataRow row in dtb.Rows)
                sum += ToDecimal(row[colName]);

            return sum;
        }

        #endregion

        #region Bind helpers

        private void BindRepeaterEmpty(Repeater rpt, Literal ltrEmpty, string message)
        {
            if (rpt == rptTeachingTimeAdded)
                ResetSumAdded();
            else if (rpt == rptTeachingHour)
                ResetSumTeaching();
            else if (rpt == rptExamDetail)
                ResetSumExam();

            rpt.DataSource = null;
            rpt.DataBind();
            ltrEmpty.Visible = true;
            ltrEmpty.Text = String.Format("<div class='alert alert-warning'>{0}</div>", message);
        }

        private void BindRepeater(Repeater rpt, Literal ltrEmpty, DataTable dtb)
        {
            ltrEmpty.Visible = false;
            ltrEmpty.Text = "";
            rpt.DataSource = dtb;
            rpt.DataBind();
        }

        protected string FormatNumber(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";

            decimal d;
            if (decimal.TryParse(value.ToString(), out d))
                return String.Format("{0:#,##0.00}", d);

            return value.ToString();
        }

        protected string FormatInteger(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";

            decimal d;
            if (decimal.TryParse(value.ToString(), out d))
                return String.Format("{0:#,##0}", d);

            return value.ToString();
        }

        protected string FormatReviewStatus(object value)
        {
            if (IsTrue(value))
                return "Đã duyệt";
            return "Chưa duyệt";
        }

        protected bool IsTrue(object value)
        {
            if (value != null && value.ToString() != "")
                return Convert.ToBoolean(value);
            return false;
        }

        #endregion
    }
}
